@js:
var window = this;
var document = {
  documentElement: { nodeName: "HTML", nodeType: 1 },
  createElement: function(tag) { return { nodeType: 1 }; },
  getElementsByTagName: function(tag) { return tag === "html" ? [{}, {}] : []; }
};

function __enc(x) {
  return encodeURIComponent(x).replace(/[!'()*]/g, function(c) {
    return '%' + c.charCodeAt(0).toString(16).toUpperCase();
  });
}

(function() {
  // 1. 取首页，提取 signJs URL 和 _t
  var homeHtml = String(java.ajax("https://www.rrssk.com/0005.html"));

  var signJsMatch = homeHtml.match(/["'](https?:\/\/[^"']*\/\?action=signJs&v=[^"']+)["']/);
  if (!signJsMatch) {
    signJsMatch = homeHtml.match(/["'](\/?\?action=signJs&v=[^"']+)["']/);
  }
  if (!signJsMatch) {
    // java.log("[-] 未找到 signJs URL");
    return;
  }
  var signJsUrl = signJsMatch[1];
  if (signJsUrl.charAt(0) === '/' || signJsUrl.charAt(0) === '?') {
    signJsUrl = "https://www.rrssk.com" + signJsUrl;
  }
  // java.log("[+] signJsUrl = " + signJsUrl);

  var verMatch = signJsUrl.match(/v=(\d+-\d+)/);
  var version = verMatch ? verMatch[1] : "default";

  var tMatch = homeHtml.match(/name="_t" value="([^"]+)"/);
  var t = tMatch ? tMatch[1] : null;
  if (!t) {
    // java.log("[-] 未找到 _t");
    return;
  }
  // java.log("[+] _t = " + t);

  // 2. 取 signJs（缓存 + 版本管理）
  var cacheKey = "rrssk_signJs";
  var signJsCode = null;
  var cachedRaw = cache.get(cacheKey);

  if (cachedRaw) {
    try {
      var cached = JSON.parse(cachedRaw);
      if (cached.version === version) {
        signJsCode = cached.code;
        // java.log("[+] 缓存命中: " + version);
      } else {
        // java.log("[+] 版本过期: " + cached.version + " -> " + version);
        cache.delete(cacheKey);
      }
    } catch (e) {
      cache.delete(cacheKey);
    }
  }

  if (!signJsCode) {
    signJsCode = String(java.ajax(signJsUrl));
    cache.put(cacheKey, JSON.stringify({
      version: version,
      code: signJsCode
    }), 86400);
    // java.log("[+] 网络拉取: " + version);
  }

  // 3. eval 执行
  eval(signJsCode);
  // java.log("[+] __SIGN_DECOY = " + window.__SIGN_DECOY);

  // 4. 计算签名
  var kw = key;
  var ts = Math.floor(Date.now() / 1000);
  var encKw = __enc(kw);
  var s = window.__SIGN.f(encKw, t, ts);

  // java.log("[+] keyword=" + kw + " _ts=" + ts + " _s=" + s);

  // 5. 返回 POST 请求
  var postBody = "_t=" + encodeURIComponent(t) +
    "&_ts=" + ts +
    "&_s=" + encodeURIComponent(s) +
    "&keyword=" + encodeURIComponent(kw);

  return "https://www.rrssk.com/?action=search," + JSON.stringify({
    method: "POST",
    body: postBody
  });
})();

